create table public.saas_features (id uuid primary key default gen_random_uuid(), key text unique not null, description text not null, created_at timestamptz not null default now());
create table public.saas_plans (id uuid primary key default gen_random_uuid(), code text unique not null check (code in ('free','premium')), name text not null, description text not null, price numeric(12,2) not null default 0, promotional_price numeric(12,2), promotion_starts_at timestamptz, promotion_ends_at timestamptz, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.saas_plan_features (plan_id uuid not null references public.saas_plans(id) on delete cascade, feature_id uuid not null references public.saas_features(id) on delete cascade, enabled boolean not null default true, primary key(plan_id, feature_id));
create table public.business_subscriptions (business_id uuid primary key references public.businesses(id) on delete cascade, plan_id uuid not null references public.saas_plans(id), status text not null default 'active' check (status in ('active','inactive','suspended')), activated_at timestamptz not null default now(), changed_at timestamptz not null default now());
create table public.saas_daily_usage (business_id uuid not null references public.businesses(id) on delete cascade, usage_date date not null, quotes_received integer not null default 0 check (quotes_received >= 0), primary key(business_id, usage_date));
create table public.saas_checkouts (id uuid primary key default gen_random_uuid(), name text not null, url text not null, description text, is_active boolean not null default false, display_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create unique index saas_one_active_checkout_idx on public.saas_checkouts(is_active) where is_active and deleted_at is null;
insert into public.saas_plans(code,name,description,price) values ('free','Free','Acesso ao sistema com limite diário de chamados.',0),('premium','Premium','Recursos liberados sem limite de chamados.',0) on conflict(code) do nothing;
insert into public.saas_features(key,description) values ('receive_quotes','Receber novos chamados'),('dashboard','Dashboard'),('analytics','Analytics'),('notifications','Notificações'),('multi_operator','Multioperador'),('future_features','Recursos futuros') on conflict(key) do nothing;
insert into public.saas_plan_features(plan_id,feature_id,enabled) select plan.id, feature.id, true from public.saas_plans plan cross join public.saas_features feature where plan.code='premium' on conflict do nothing;
insert into public.saas_plan_features(plan_id,feature_id,enabled) select plan.id, feature.id, true from public.saas_plans plan join public.saas_features feature on feature.key in ('receive_quotes','dashboard','notifications','multi_operator') where plan.code='free' on conflict do nothing;
create or replace function private.enforce_saas_quote_limit() returns trigger language plpgsql security definer set search_path=public as $$ declare subscription public.business_subscriptions; usage_row public.saas_daily_usage; premium boolean; begin select * into subscription from public.business_subscriptions where business_id=new.business_id and status='active'; premium := subscription.plan_id is not null and exists(select 1 from public.saas_plans where id=subscription.plan_id and code='premium'); if premium then return new; end if; insert into public.saas_daily_usage(business_id,usage_date,quotes_received) values(new.business_id,current_date,0) on conflict do nothing; select * into usage_row from public.saas_daily_usage where business_id=new.business_id and usage_date=current_date for update; if usage_row.quotes_received >= 3 then raise exception 'free_daily_quote_limit_reached'; end if; update public.saas_daily_usage set quotes_received=quotes_received+1 where business_id=new.business_id and usage_date=current_date; return new; end; $$;
create trigger enforce_saas_quote_limit before insert on public.quote_notifications for each row execute function private.enforce_saas_quote_limit();
alter table public.saas_features enable row level security; alter table public.saas_plans enable row level security; alter table public.saas_plan_features enable row level security; alter table public.business_subscriptions enable row level security; alter table public.saas_daily_usage enable row level security; alter table public.saas_checkouts enable row level security;
create policy saas_public_plans_read on public.saas_plans for select to authenticated using(is_active); create policy saas_public_features_read on public.saas_features for select to authenticated using(true); create policy saas_plan_features_read on public.saas_plan_features for select to authenticated using(true); create policy saas_business_subscription_read on public.business_subscriptions for select to authenticated using(exists(select 1 from public.business_employees e where e.business_id=business_subscriptions.business_id and e.profile_id=auth.uid() and e.is_active and e.deleted_at is null)); create policy saas_daily_usage_read on public.saas_daily_usage for select to authenticated using(exists(select 1 from public.business_employees e where e.business_id=saas_daily_usage.business_id and e.profile_id=auth.uid() and e.is_active and e.deleted_at is null)); create policy saas_checkout_read on public.saas_checkouts for select to authenticated using(is_active and deleted_at is null);
